464: // WaitForServer waits for the Ollama server to be ready
465: func WaitForServer(ctx context.Context, timeout time.Duration) error {
466: 	deadline := time.Now().Add(timeout)
467: 	for time.Now().Before(deadline) {
468: 		c, err := api.ClientFromEnvironment()
469: 		if err != nil {
470: 			return err
471: 		}
472: 		if _, err := c.Version(ctx); err == nil {
473: 			slog.Debug("ollama server is ready")
474: 			return nil
475: 		}
476: 		time.Sleep(10 * time.Millisecond)
477: 	}
478: 	return errors.New("timeout waiting for Ollama server to be ready")
479: }
